/// <summary>
/// PricingAttribute of table <c>SalesLine</c> field ItemBOMId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeSalesLineItemBOMId extends UPSPricingAttributeSalesLine implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesLine, ItemBOMId);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::String);
    SalesLine   salesLine;

    while select salesLine
        group by ItemBOMId
    {
        if (! ret.in(salesLine.ItemBOMId))
        {
            ret.add(salesLine.ItemBOMId);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesLine, ItemBOMId));
    qbr.value(queryValue(_value));
}
